final class NativeSelectedPhotoControllerTests: XCTestCase {
    private func ready() -> NativePhotoHarness {
        let model = NativePhotoHarness(); let view = UUID(); model.beginExplorePresentation(view)
        let selection = model.beginSelectedPhoto(viewID: view)!
        let identity = CompanionReferenceIdentity(sourceID: selection.id, revision: UUID(), sha256: String(repeating: "a", count: 64), media: .selectedPhoto)
        let text = String(repeating: "Do not remove this warning. ", count: 20)
        let evidence = CompanionEvidence(id: "one", kind: .historicalMemory, text: text, source: identity.evidenceSource)
        let source = CompanionReferenceSource(identity: identity, toolResult: .init(status: .success, source: identity.evidenceSource, evidence: [evidence]),
            blocks: [.init(evidence: evidence, bodyUTF16Range: NSRange(location: 0, length: text.utf16.count), locator: "selected photo")])
        XCTAssertTrue(model.selectedPhoto.install(source, for: selection, now: ProcessInfo.processInfo.systemUptime)); return model
    }
    func testActualPhotoRouterNeverCancelsNavigationSearchOrHazards() {
        let m = NativePhotoHarness(); let route = m.routeToken, search = m.searchToken, perception = m.perceptionToken
        XCTAssertTrue(m.routeSelectedPhotoInquiry("Where is the door in this photo?", origin: .trustedInterface))
        XCTAssertTrue(m.showPhotoReference); XCTAssertTrue(m.photoPickerRequested); XCTAssertEqual(m.interruptedOrdinary, 1)
        XCTAssertEqual(m.routeToken, route); XCTAssertEqual(m.searchToken, search); XCTAssertEqual(m.perceptionToken, perception); XCTAssertEqual(m.goal, "Find my coat"); XCTAssertFalse(m.cancelledTask)
    }
    func testPhotoRouterHasNoSourceOutsideViewAndRejectsModelAuthoredActions() {
        let m = NativePhotoHarness(); XCTAssertFalse(m.routeSelectedPhotoInquiry("Read this photo", origin: .modelOutput)); XCTAssertFalse(m.showPhotoReference)
        XCTAssertTrue(m.routeSelectedPhotoInquiry("Read this photo", origin: .trustedInterface)); XCTAssertNil(m.selectedPhoto.source); XCTAssertNil(m.beginSelectedPhoto(viewID: UUID())); XCTAssertTrue(m.dispatched.isEmpty)
    }
    func testActiveViewReusesExistingPickerRatherThanAddingAnotherView() {
        let m = NativePhotoHarness(); m.beginExplorePresentation(UUID())
        XCTAssertTrue(m.routeSelectedPhotoInquiry("Read this photo", origin: .trustedInterface)); XCTAssertFalse(m.showPhotoReference); XCTAssertTrue(m.photoPickerRequested)
    }
    func testUnverifiedSpeechCannotOpenPickerReadOrReplaceAnOwnedPrivateSource() {
        for origin in [CompanionCommandOrigin.unverifiedMicrophone, .modelOutput, .observedContent, .unknown] {
            let m = ready(); let source = m.selectedPhoto.source!.identity
            XCTAssertFalse(m.routeSelectedPhotoInquiry("Read the selected photo", origin: origin))
            XCTAssertEqual(m.selectedPhoto.source?.identity, source)
            XCTAssertFalse(m.showPhotoReference); XCTAssertFalse(m.photoPickerRequested)
            XCTAssertTrue(m.dispatched.isEmpty); XCTAssertEqual(m.interruptedOrdinary, 0)
        }
    }
