        let m = ready(); m.speakNextSelectedPhotoPhrase(); let id = m.dispatched[0].1
        XCTAssertTrue(m.routeSelectedPhotoInquiry("Where is my bag in the selected photo?", origin: .trustedInterface))
        XCTAssertEqual(m.feedback.stopped, [id]); XCTAssertNil(m.selectedPhoto.selection); XCTAssertNil(m.selectedPhoto.source)
